/** The aria-label each listed control renders (null when it is not on screen). Equal in both apps when the names are right. */
async function accessibleNames(app: AppHandle): Promise<Record<string, string | null>> {
  const out: Record<string, string | null> = {};
  for (const [canvas, code] of ACCESSIBLE) {
    const el = app.kind === "canvas" ? app.frame.locator(`[data-control-name='${canvas}']`).first() : app.frame.getByTestId(code).first();
    if ((await el.count()) === 0) { out[canvas] = null; continue; }
    const own = await el.getAttribute("aria-label", { timeout: 2_000 }).catch(() => null);
    const inner = el.locator("[aria-label]").first();
    out[canvas] = own ?? ((await inner.count()) > 0 ? await inner.getAttribute("aria-label", { timeout: 2_000 }).catch(() => null) : null);
  }
  return out;
}

